segments.en:
Likutay Halachos – Hilchos Tzitzis 3

@import url('https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400;0,500;0,600;0,700;1,400;1,500&family=Frank+Ruhl+Libre:wght@400;500;700&display=swap');

:root {

--text-color: #2a2218;

--bg-color: #faf6f0;

--accent-color: #6b4c2a;

--heading-color: #3d2b14;

--verse-color: #4a3520;

--verse-bg: #f3ede4;

--note-color: #7a6b5a;

--border-color: #d4c8b8;

* { margin: 0; padding: 0; box-sizing: border-box; }

body {

font-family: 'EB Garamond', 'Georgia', serif;

font-size: 18px;

line-height: 1.85;

color: var(--text-color);

background: var(--bg-color);

max-width: 780px;

margin: 0 auto;

padding: 40px 28px 80px;

text-align: justify;

font-family: 'Frank Ruhl Libre', 'EB Garamond', serif;

font-size: 28px;

font-weight: 700;

color: var(--heading-color);

text-align: center;

margin-bottom: 6px;

letter-spacing: 0.5px;

font-family: 'Frank Ruhl Libre', 'EB Garamond', serif;

font-size: 20px;

font-weight: 500;

color: var(--accent-color);

text-align: center;

margin-bottom: 30px;

font-style: italic;

font-family: 'Frank Ruhl Libre', 'EB Garamond', serif;

font-size: 21px;

font-weight: 600;

color: var(--heading-color);

margin: 36px 0 16px;

text-align: center;

p { margin-bottom: 18px; text-indent: 2em; }

p.no-indent { text-indent: 0; }

.key-term { font-style: italic; }

.transliteration { font-style: italic; }

.heb { font-family: 'Frank Ruhl Libre', serif; direction: rtl; unicode-bidi: isolate; font-style: normal; }

.bracket-def { font-size: 16px; color: var(--note-color); }

.bold-concept { font-weight: 600; }

.section-divider { text-align: center; margin: 32px 0; color: var(--border-color); letter-spacing: 8px; font-size: 14px; }

.zohar-quote { font-style: italic; }

sup { font-size: 13px; color: var(--note-color); }

.source { font-style: normal; font-size: 15px; color: var(--note-color); }

.footnotes-section {

margin-top: 60px;

border-top: 1px solid var(--border-color);

padding-top: 24px;

.footnotes-section h3 { font-size: 18px; margin-bottom: 12px; }

.footnote-item { font-size: 15px; line-height: 1.7; color: var(--note-color); margin-bottom: 8px; text-indent: 0; }
